                BluetoothDevice device = adapter.getRemoteDevice(address);
                gatt = device.connectGatt(activity, false, gattCallback, BluetoothDevice.TRANSPORT_LE);
                if (gatt == null) send("OnAndroidBleError", "Could not start BLE connection.");
            } catch (IllegalArgumentException exception) {
                send("OnAndroidBleError", "Invalid device address.");
            }
        });
    }

    public static void disconnect() {
        if (activity == null) return;
        activity.runOnUiThread(() -> {
            stopScan();
            if (gatt != null) {
                gatt.disconnect();
                gatt.close();
                gatt = null;
            }
        });
    }

    private static void beginScan() {
        BluetoothManager manager = (BluetoothManager) activity.getSystemService(Context.BLUETOOTH_SERVICE);
