package com.wristconductor.ble;

import android.app.Activity;
import android.bluetooth.BluetoothAdapter;
import android.bluetooth.BluetoothDevice;
import android.bluetooth.BluetoothGatt;
import android.bluetooth.BluetoothGattCallback;
import android.bluetooth.BluetoothGattCharacteristic;
import android.bluetooth.BluetoothGattDescriptor;
import android.bluetooth.BluetoothManager;
import android.bluetooth.le.BluetoothLeScanner;
import android.bluetooth.le.ScanCallback;
import android.bluetooth.le.ScanResult;
import android.content.Context;
import android.os.Build;
import android.util.Base64;

import com.unity3d.player.UnityPlayer;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

/** Generic BLE scanner and notification subscriber for Unity Android builds. */
public final class UnityBlePlugin {
    private static final String CCCD_UUID = "00002902-0000-1000-8000-00805f9b34fb";
    private static Activity activity;
    private static BluetoothAdapter adapter;
    private static BluetoothLeScanner scanner;
    private static BluetoothGatt gatt;
    private static String gameObjectName;
    private static String serviceUuidText;
    private static String notifyCharacteristicUuidText;
    private static UUID serviceUuid;
    private static UUID notifyCharacteristicUuid;
    private static String requiredName;
    private static final Set<String> reportedAddresses = new HashSet<>();

    private UnityBlePlugin() { }

    public static void startScan(String unityGameObject, String service, String characteristic, String nameFilter) {
        activity = UnityPlayer.currentActivity;
        gameObjectName = unityGameObject;
        serviceUuidText = service;
        notifyCharacteristicUuidText = characteristic;
        requiredName = nameFilter == null ? "" : nameFilter.trim();
        activity.runOnUiThread(() -> beginScan());
    }

    public static void connect(String address) {
        if (activity == null || adapter == null) {
            send("OnAndroidBleError", "Start a scan before connecting.");
            return;
        }
        activity.runOnUiThread(() -> {
            try {
                serviceUuid = UUID.fromString(serviceUuidText);
                notifyCharacteristicUuid = UUID.fromString(notifyCharacteristicUuidText);
                stopScan();
                if (gatt != null) {
                    gatt.close();
                    gatt = null;
                }
                BluetoothDevice device = adapter.getRemoteDevice(address);
                gatt = device.connectGatt(activity, false, gattCallback, BluetoothDevice.TRANSPORT_LE);
                if (gatt == null) send("OnAndroidBleError", "Could not start BLE connection.");
            } catch (IllegalArgumentException exception) {
                send("OnAndroidBleError", "Invalid UUID or device address.");
            }
        });
    }

    public static void disconnect() {
        if (activity == null) return;
        activity.runOnUiThread(() -> {
            stopScan();
            if (gatt != null) {
                gatt.disconnect();
                gatt.close();
                gatt = null;
            }
        });
    }

    private static void beginScan() {
        BluetoothManager manager = (BluetoothManager) activity.getSystemService(Context.BLUETOOTH_SERVICE);
        adapter = manager == null ? null : manager.getAdapter();
        if (adapter == null || !adapter.isEnabled()) {
            send("OnAndroidBleError", "Bluetooth is unavailable or disabled.");
            return;
        }
        scanner = adapter.getBluetoothLeScanner();
        if (scanner == null) {
            send("OnAndroidBleError", "BLE scanning is unavailable.");
            return;
        }
        reportedAddresses.clear();
        scanner.startScan(scanCallback);
        send("OnAndroidBleStatus", "Scanning");
    }

    private static void stopScan() {
        if (scanner != null) {
            scanner.stopScan(scanCallback);
            scanner = null;
        }
    }

    private static final ScanCallback scanCallback = new ScanCallback() {
        @Override public void onScanResult(int callbackType, ScanResult result) {
            BluetoothDevice device = result.getDevice();
            String name = device.getName();
            if (!requiredName.isEmpty() && !requiredName.equals(name)) return;
            String address = device.getAddress();
            if (address == null || !reportedAddresses.add(address)) return;
            String displayName = name == null ? "" : name;
            send("OnAndroidBleDeviceFound", urlEncode(displayName + "\n" + address));
        }

        @Override public void onScanFailed(int errorCode) {
            send("OnAndroidBleError", "BLE scan failed: " + errorCode);
        }
    };

    private static final BluetoothGattCallback gattCallback = new BluetoothGattCallback() {
        @Override public void onConnectionStateChange(BluetoothGatt connection, int status, int newState) {
            if (status != BluetoothGatt.GATT_SUCCESS || newState == BluetoothGatt.STATE_DISCONNECTED) {
                send("OnAndroidBleDisconnected", "");
                return;
            }
            if (newState == BluetoothGatt.STATE_CONNECTED) connection.discoverServices();
        }

        @Override public void onServicesDiscovered(BluetoothGatt connection, int status) {
            if (status != BluetoothGatt.GATT_SUCCESS) {
                send("OnAndroidBleError", "Service discovery failed: " + status);
                return;
            }
            BluetoothGattCharacteristic characteristic = null;
            if (connection.getService(serviceUuid) != null)
                characteristic = connection.getService(serviceUuid).getCharacteristic(notifyCharacteristicUuid);
            if (characteristic == null) {
                send("OnAndroidBleError", "Configured notification characteristic was not found.");
                return;
            }
            if (!connection.setCharacteristicNotification(characteristic, true)) {
                send("OnAndroidBleError", "Could not enable notifications.");
                return;
            }
            BluetoothGattDescriptor descriptor = characteristic.getDescriptor(UUID.fromString(CCCD_UUID));
            if (descriptor == null) {
                send("OnAndroidBleError", "Notification descriptor was not found.");
                return;
            }
            descriptor.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);
            if (!connection.writeDescriptor(descriptor))
                send("OnAndroidBleError", "Could not subscribe to notifications.");
        }

        @Override public void onDescriptorWrite(BluetoothGatt connection, BluetoothGattDescriptor descriptor, int status) {
            if (status == BluetoothGatt.GATT_SUCCESS) send("OnAndroidBleConnected", "");
            else send("OnAndroidBleError", "Notification subscription failed: " + status);
        }

        @Override public void onCharacteristicChanged(BluetoothGatt connection, BluetoothGattCharacteristic characteristic) {
            byte[] value = characteristic.getValue();
            if (value != null) send("OnAndroidBleData", Base64.encodeToString(value, Base64.NO_WRAP));
        }
    };

    private static void send(String method, String value) {
        if (gameObjectName != null) UnityPlayer.UnitySendMessage(gameObjectName, method, value == null ? "" : value);
    }

    private static String urlEncode(String value) {
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU)
                return URLEncoder.encode(value, StandardCharsets.UTF_8);
            return URLEncoder.encode(value, "UTF-8");
        } catch (Exception ignored) {
            return value;
        }
    }
}

